import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"插件测试与验收","description":"","frontmatter":{},"headers":[],"relativePath":"developers/testing.md","filePath":"developers/testing.md","lastUpdated":1791895515000}'),r={name:"developers/testing.md"};function i(n,t,o,l,h,p){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="插件测试与验收" tabindex="-1">插件测试与验收 <a class="header-anchor" href="#插件测试与验收" aria-label="Permalink to &quot;插件测试与验收&quot;">​</a></h1><p>插件作者不需要运行宿主内部测试。先验证自己的库与包，再在已安装宿主上做集成验收。静态检查、手机交互和听感判断分开记录。</p><h2 id="编译与包检查" tabindex="-1">编译与包检查 <a class="header-anchor" href="#编译与包检查" aria-label="Permalink to &quot;编译与包检查&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/build.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>脚本编译 C 示例为 AArch64 ELF，检查导出入口并生成 ZIP。网站仓库的 <code>npm run check</code> 还检查公开参考覆盖、SDK 一致性、内部链接、源码泄露边界与示例 C 语法。</p><p>自己的包检查清单：manifest 与入口 ID/能力一致；ABI 3；entry 是同级文件名；ZIP 没有越界路径；图标/说明与实际许可证一致；平台和架构匹配设备。</p><h2 id="集成场景" tabindex="-1">集成场景 <a class="header-anchor" href="#集成场景" aria-label="Permalink to &quot;集成场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>验收</th></tr></thead><tbody><tr><td>所有插件</td><td>安装、活动状态、错误回退、卸载、重启</td></tr><tr><td>UI</td><td>点击与拖动、窗口变化、切歌、暂停、返回、连续操作</td></tr><tr><td>参数</td><td>默认值、错误类型、界限、写入下一帧可见、重启持久化</td></tr><tr><td>模式</td><td>空/单首队列、首尾边界、手动与自动、真实顺序一致</td></tr><tr><td>播放</td><td>seek、锁屏、长后台、音频焦点、设备路由、提供者退出</td></tr><tr><td>数据</td><td>revision 变化、旧结果拒绝、UTF-8 长字符串、无歌词</td></tr><tr><td>网络</td><td>超时、坏签名、坏摘要、旧缓存、镜像失败、取消</td></tr></tbody></table><p>不要在稳定帧反复分配大缓冲，不在音频实时回调做网络或磁盘操作。quiesce 必须等待线程真正退出，不用固定延时伪装。</p><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><p>记录宿主版本、SDK ABI、插件版本、设备系统/架构、复现动作、实际结果、期望结果和错误日志。不要提交用户歌词正文、私钥或签名密码。静音/mock 测试不能证明音频质量，编译通过不能证明 UI 观感。</p><p>日志获取与恢复限制见<a href="/LyraPlayer-docs-site/plugins/troubleshooting">排错</a>。</p>',12)])])}const b=e(r,[["render",i]]);export{u as __pageData,b as default};
